#include <iostream>#include <vector>#include <string>using namespace std;//  Structstruct Aluno {    string nome;    int idade;    float nota;};//  Vectorvector<Aluno> alunos;//  Funcao adicionar alunovoid adicionarAluno() {    Aluno novo;    cout << endl;    cout << "Nome do aluno: ";    cin >> novo.nome;    cout << "Idade: ";    cin >> novo.idade;    cout << "Nota final: ";    cin >> novo.nota;    alunos.push_back(novo);    cout << endl;    cout << "Aluno adicionado com sucesso 😄" << endl;}//  Mostrar alunosvoid mostrarAlunos() {    cout << endl;    cout << "=== LISTA DE ALUNOS ===" << endl;    if (alunos.empty()) {        cout << "Nenhum aluno registado 😢" << endl;    } else {        for (int i = 0; i < alunos.size(); i++) {            cout << endl;            cout << "Aluno #" << i + 1 << endl;            cout << "Nome: " << alunos[i].nome << endl;            cout << "Idade: " << alunos[i].idade << endl;            cout << "Nota: " << alunos[i].nota << endl;            if (alunos[i].nota >= 10) {                cout << "Status: Aprovado 😄" << endl;            } else {                cout << "Status: Reprovado 😢" << endl;            }        }    }}//  Calcular media geralfloat calcularMediaTurma() {    float soma = 0;    for (int i = 0; i < alunos.size(); i++) {        soma += alunos[i].nota;    }    if (alunos.size() > 0) {        return soma / alunos.size();    }    return 0;}int main() {    int opcao;    do {        cout << endl;        cout << "=== SISTEMA ESCOLAR 🚀 ===" << endl;        cout << "1 - Adicionar aluno" << endl;        cout << "2 - Mostrar alunos" << endl;        cout << "3 - Media da turma" << endl;        cout << "0 - Sair" << endl;        cout << "Opcao: ";        cin >> opcao;        if (opcao == 1) {            adicionarAluno();        }        else if (opcao == 2) {            mostrarAlunos();        }        else if (opcao == 3) {            float media = calcularMediaTurma();            cout << endl;            cout << "Media da turma: " << media << endl;        }        else if (opcao == 0) {            cout << "Saindo do sistema 👋" << endl;        }        else {            cout << "Opcao invalida 😅" << endl;        }    } while (opcao != 0);    return 0;}